//! B27 native CVNSS codec.
mod rules;pub mod cvnss;pub mod stream;
pub mod lz;pub mod huffman;pub mod range;
use sha2::{Sha256,Digest};
pub const LIMIT:usize=16*1024*1024;
#[no_mangle]pub extern "C" fn b27_pack5(a:u32,b:u32,c:u32,d:u32,e:u32)->u32{let s=[a,b,c,d,e];if s.iter().any(|&x|x>=27){return u32::MAX}s.iter().fold(0,|v,x|v*27+x)}
#[no_mangle]pub extern "C" fn b27_digit(v:u32,i:u32)->u32{if v>=27u32.pow(5)||i>=5{return u32::MAX}(v/27u32.pow(4-i))%27}
pub fn payload_encode(b:&[u8],tag:u8)->Result<Vec<u8>,&'static str>{if b.len()>LIMIT*6+1024{return Err("limit")}match tag{0=>Ok(b.to_vec()),1..=3=>Ok(huffman::encode(b)),4..=6=>Ok(lz::encode(b)),7..=9=>Ok(range::encode(&lz::encode(b))),_=>Err("mode")}}
pub fn payload_decode(b:&[u8],tag:u8,limit:usize)->Result<Vec<u8>,&'static str>{if limit>LIMIT*6+1024{return Err("limit")}match tag{0 if b.len()<=limit=>Ok(b.to_vec()),1..=3=>huffman::decode(b,limit),4..=6=>lz::decode(b,limit),7..=9=>lz::decode(&range::decode(b,limit.saturating_mul(2)+1024)?,limit),_=>Err("mode/limit")}}
pub fn compress(b:&[u8],mode:u8)->Result<Vec<u8>,&'static str>{if b.len()>LIMIT{return Err("limit")}let(mut tag,mut p)=(0,b.to_vec());if mode==255{let t=cvnss::transform(b,false);let q=cvnss::transform(b,true);for (kind,x) in [(0,b),(1,t.as_slice()),(2,q.as_slice())]{for base in [1,4,7]{let k=base+kind;if let Ok(y)=payload_encode(x,k){if y.len()<p.len(){p=y;tag=k}}}}}else{if mode>9{return Err("mode")}tag=mode;let kind=if mode==0{0}else{(mode-1)%3};let t=if kind>0{cvnss::transform(b,kind==2)}else{b.to_vec()};p=payload_encode(&t,tag)?}let mut out=b"B27N".to_vec();out.push(tag);out.extend_from_slice(&(b.len() as u32).to_be_bytes());out.extend_from_slice(&Sha256::digest(b));out.extend(p);Ok(out)}
pub fn decompress(b:&[u8])->Result<Vec<u8>,&'static str>{use std::io::Read;if b.len()<41||b.len()>LIMIT*15+4096{return Err("header/limit")}let tag=b[4];let n=u32::from_be_bytes(b[5..9].try_into().unwrap()) as usize;if n>LIMIT{return Err("limit")}let mid=n.saturating_mul(6).saturating_add(1024);let p=if &b[..4]==b"B27F"{if tag>3{return Err("mode")}let q=if tag==0{if b.len()-41!=n{return Err("length")}b[41..].to_vec()}else{let mid=if tag==1{n}else{mid};let mut q=vec![];flate2::read::DeflateDecoder::new(&b[41..]).take((mid+1)as u64).read_to_end(&mut q).map_err(|_|"deflate")?;if q.len()>mid{return Err("limit")}q};if tag>=2{cvnss::inverse(&q,n)?}else{q}}else if &b[..4]==b"B27N"{if tag>9{return Err("mode")}let kind=if tag==0{0}else{(tag-1)%3};let q=payload_decode(&b[41..],tag,if kind==0{n}else{mid})?;if kind>0{cvnss::inverse(&q,n)?}else{q}}else{return Err("magic")};if p.len()!=n||Sha256::digest(&p)[..]!=b[9..41]{return Err("integrity")}Ok(p)}
// WASM ABI owns buffers in linear memory; callers copy data before next operation.
use std::cell::RefCell;
thread_local!{static INPUT:RefCell<Vec<u8>>=const{RefCell::new(Vec::new())};static OUTPUT:RefCell<Vec<u8>>=const{RefCell::new(Vec::new())};}
#[no_mangle]pub extern "C" fn b27_input(n:u32)->*mut u8{if n as usize>LIMIT*3+2048{INPUT.with(|x|x.borrow_mut().clear());return std::ptr::null_mut()}INPUT.with(|x|{let mut x=x.borrow_mut();x.resize(n as usize,0);x.as_mut_ptr()})}
#[no_mangle]pub extern "C" fn b27_run(op:u32,mode:u32,limit:u32)->i32{OUTPUT.with(|o|o.borrow_mut().clear());if mode>255{return -1}let r=INPUT.with(|x|{let x=x.borrow();match op{0=>compress(&x,mode as u8),1=>decompress(&x),2=>payload_encode(&x,mode as u8),3=>payload_decode(&x,mode as u8,limit as usize),4=>cvnss::api_json(&x),5=>{let mut out=Vec::new();stream::encode(&x[..],&mut out,mode as u8).map(|_|out).map_err(|_|"stream")},6=>{if limit>64*1024*1024{return Err("wasm output limit")}let mut out=Vec::new();stream::decode(&x[..],&mut out,limit as u64).map(|_|out).map_err(|_|"stream")},_=>Err("op")}});match r{Ok(v)=>{OUTPUT.with(|o|*o.borrow_mut()=v);0},Err(_)=>-1}}
#[no_mangle]pub extern "C" fn b27_output_ptr()->*const u8{OUTPUT.with(|o|o.borrow().as_ptr())}
#[no_mangle]pub extern "C" fn b27_output_len()->u32{OUTPUT.with(|o|o.borrow().len() as u32)}
#[cfg(test)]mod tests{use super::*;#[test]fn roundtrip(){let mut seed=42u32;for n in 0..256{let x:Vec<_>=(0..n).map(|_|{seed=seed.wrapping_mul(1664525).wrapping_add(1013904223);(seed>>24)as u8}).collect();for m in [0,1,4,7,255]{let y=compress(&x,m).unwrap();assert_eq!(decompress(&y).unwrap(),x);let mut z=y;z[9]^=1;assert!(decompress(&z).is_err())}}}#[test]fn base(){assert_eq!(b27_pack5(26,26,26,26,26),14348906);assert_eq!(b27_digit(14348906,4),26)}}
